import pandas as pd
import numpy as np

# Load data
no2_path = "chunks_csv/getisord/getisord_no2_Q3_2022.csv"
adjacency_path = "chunks_csv/borough_adjacency.csv"
df_no2 = pd.read_csv(no2_path)
df_adj = pd.read_csv(adjacency_path)

# Remove rows with missing NO2 values
df_no2_clean = df_no2.dropna(subset=['avg_no2_value'])
valid_boroughs = set(df_no2_clean['borough'])
n = len(df_no2_clean)  # data_points_used

# Build undirected graph from adjacency data
graph = {}
for _, row in df_adj.iterrows():
    a = row['borough']
    b = row['neighbor']
    if a not in graph:
        graph[a] = set()
    graph[a].add(b)
    if b not in graph:
        graph[b] = set()
    graph[b].add(a)

# Create neighborhoods including self and valid neighbors
neighborhoods = {}
for borough in valid_boroughs:
    neighborhood_set = {borough}
    if borough in graph:
        for neighbor in graph[borough]:
            if neighbor in valid_boroughs:
                neighborhood_set.add(neighbor)
    neighborhoods[borough] = list(neighborhood_set)

# Compute global statistics
global_mean = df_no2_clean['avg_no2_value'].mean()
global_std = df_no2_clean['avg_no2_value'].std(ddof=1)  # sample standard deviation

# Prepare NO2 values for quick lookup
no2_series = df_no2_clean.set_index('borough')['avg_no2_value']

# Calculate Gi* z-scores
results = []
for borough in valid_boroughs:
    neigh_list = neighborhoods[borough]
    W_i = len(neigh_list)
    S_i = no2_series[neigh_list].sum()
    numerator = S_i - (W_i * global_mean)
    denom_factor = (n * W_i - W_i**2) / (n - 1)
    if denom_factor < 0:
        denominator = 0
    else:
        denominator = global_std * np.sqrt(denom_factor)
    if denominator == 0:
        z_score = 0
    else:
        z_score = numerator / denominator
    if z_score > 1.96:
        results.append((borough, z_score, 'HOT'))
    elif z_score < -1.96:
        results.append((borough, z_score, 'COLD'))

# Output data points used
print(f"data_points_used = {n}")

# Format and print final results
if results:
    formatted_results = []
    for borough, z_score, spot_type in results:
        formatted_results.append(f"{borough} ({spot_type}, Gi*={z_score:.4f})")
    print(f"FINAL ANSWER: {', '.join(formatted_results)}")
else:
    print("FINAL ANSWER: none")
